/** Source: cable_club.c → Task_ValidateMixingGameLanguage */
export const Task_ValidateMixingGameLanguage: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let playerCount = 0;
      let i = 0;

      switch (task.data[0])
      {
      case 0:
          if (gSpecialVar_Result == LINKUP_SUCCESS)
          {
              let mixingForeignGames = false;
              let isEnglishRSLinked = false;
              let isJapaneseEmeraldLinked = false;

              playerCount = GetLinkPlayerCount();
              for (i = 0; i < playerCount; i++)
              {
                  let version = gLinkPlayers[i].version;
                  let language = gLinkPlayers[i].language;

                  if (version == VERSION_RUBY || version == VERSION_SAPPHIRE)
                  {
                      if (language == LANGUAGE_JAPANESE)
                      {
                          mixingForeignGames = true;
                          break;
                      }
                      else
                      {
                          isEnglishRSLinked = true;
                      }
                  }
                  else if (version == VERSION_EMERALD)
                  {
                      if (language == LANGUAGE_JAPANESE)
                      {
                          isJapaneseEmeraldLinked = true;
                      }
                  }
              }

              if (isEnglishRSLinked && isJapaneseEmeraldLinked)
              {
                  mixingForeignGames = true;
              }

              if (mixingForeignGames)
              {
                  gSpecialVar_Result = LINKUP_FOREIGN_GAME;
                  SetCloseLinkCallbackHandleJP();
                  task.data[0] = 1;
                  return;
              }
          }
          ScriptContext_Enable();
          rt.DestroyTask(taskId);
          break;
      case 1:
          if (!gReceivedRemoteLinkPlayers)
          {
              ScriptContext_Enable();
              rt.DestroyTask(taskId);
          }
          break;
      }
};

